import symbol2shape = require( './index' );


// TESTS //

// The function returns a string or null...
{
	symbol2shape( 'o' ); // $ExpectType string | null
}

// The compiler throws an error if the function is not provided a string...
{
	symbol2shape( 1 ); // $ExpectError
	symbol2shape( true ); // $ExpectError
	symbol2shape( false ); // $ExpectError
	symbol2shape( null ); // $ExpectError
	symbol2shape( undefined ); // $ExpectError
	symbol2shape( [] ); // $ExpectError
	symbol2shape( {} ); // $ExpectError
	symbol2shape( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	symbol2shape(); // $ExpectError
	symbol2shape( 'o', {} ); // $ExpectError
}
